//! The pet core against its spec: the design's reference renderer
//! (`tests/golden.json`, generated by moshpit-design `tools/golden.py`
//! from `tools/build.py`), the roll's distribution, growing up, mutations,
//! the easter eggs, the merge laws and the Live Activity's encoding.

use std::collections::BTreeMap;

use serde_json::Value;
use sha2::{Digest, Sha256};

use crate::art::{art, parse_bundled};
use crate::easter::{self, Egg, Taps};
use crate::genome::{
    Eyes, Genome, Growth, Mutation, Pattern, Seed, Size, Slot, Species, Stage, evolve,
};
use crate::record::{EggProgress, PetRecord, RecordError, Thresholds, may_hatch, merge, reconcile};
use crate::sprite::{Appearance, EggPose, Extras, Look, Pose, Sprite, compose_frame, egg};

const GOLDEN: &str = include_str!("../tests/golden.json");
const DAY: i64 = 86_400;

fn seed_of(hex: &str) -> Seed {
    let bytes: Vec<u8> = (0..hex.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&hex[i..i + 2], 16).unwrap())
        .collect();
    Seed::try_from(bytes).unwrap()
}

fn seed_n(n: u32) -> Seed {
    let d: [u8; 32] = Sha256::digest(format!("test seed {n}")).into();
    Seed::try_from(&d[..16]).unwrap()
}

/// The reference's digest: every cell's `#RRGGBB` (or `.`), row by row.
fn digest(s: &Sprite, appearance: Appearance) -> String {
    let side = usize::from(s.side);
    let mut flat = String::new();
    for y in 0..side {
        for x in 0..side {
            match s.color(x, y, appearance) {
                Some(c) => flat.push_str(&format!("#{c:06X}")),
                None => flat.push('.'),
            }
        }
    }
    Sha256::digest(flat.as_bytes())
        .iter()
        .map(|b| format!("{b:02x}"))
        .collect()
}

fn mode(m: &str) -> Appearance {
    if m == "light" {
        Appearance::Light
    } else {
        Appearance::Dark
    }
}

// ---- the art ---------------------------------------------------------

#[test]
fn the_art_parses_and_every_key_has_a_colour_in_both_appearances() {
    let art = parse_bundled().expect("pixel.json parses");
    for (id, ch) in &art.characters {
        // Everything a species can be drawn with: props, accessories, its
        // template's parts and its own.
        let mut parts: Vec<(&String, &crate::art::Part)> = art.props.iter().collect();
        parts.extend(art.accessories.iter().map(|(k, a)| (k, &a.part)));
        if let Some(t) = ch.template.as_deref() {
            parts.extend(art.characters[t].parts.iter());
        }
        parts.extend(ch.parts.iter());
        for (look, props, own) in [
            ("light", &art.props_palette.light, &ch.palette.light),
            ("dark", &art.props_palette.dark, &ch.palette.dark),
        ] {
            for (name, part) in &parts {
                let width = part.rows.first().map_or(0, Vec::len);
                assert!(
                    part.rows.iter().all(|r| r.len() == width),
                    "{id}/{name}: rows of different widths"
                );
                for key in part.rows.iter().flatten().filter(|k| **k != '.') {
                    assert!(
                        own.contains_key(key) || props.contains_key(key),
                        "{id}/{name}: {key:?} has no {look} colour"
                    );
                }
            }
        }
    }
    assert_eq!(
        art.genome.furs.len(),
        10,
        "the species' own colours and nine furs"
    );
    assert!(
        art.genome.furs[0].colors.is_none()
            && art.genome.furs[1..].iter().all(|f| f.colors.is_some())
    );
    for (slot, ids) in &art.genome.grown {
        for id in ids {
            assert!(
                Growth::from_id(id).is_some() && art.accessories.contains_key(id),
                "{slot}: {id}"
            );
        }
    }
    for ch in art.characters.values() {
        for marks in ch.stage_marks.values() {
            assert!(
                marks.iter().all(|m| art.accessories.contains_key(m)),
                "a stage mark that isn't an accessory"
            );
        }
    }
}

#[test]
fn every_species_has_every_state_in_every_stage_and_each_frame_composes() {
    let art = art();
    let total: u32 = Species::ALL.iter().map(|s| s.weight()).sum();
    assert_eq!(total, 1000, "the weights are out of 1000");
    for species in Species::ALL {
        let states = art
            .states(species.id())
            .unwrap_or_else(|| panic!("{species:?} has no frames"));
        for pose in Pose::STATES {
            let frames = states
                .get(pose.id())
                .unwrap_or_else(|| panic!("{species:?} has no {}", pose.id()));
            assert!(
                !frames.is_empty() && frames.len() <= 4,
                "{species:?}/{}: 1–4 frames",
                pose.id()
            );
            for stage in Stage::ALL {
                for frame in frames {
                    for layer in &frame.layers {
                        let known = layer.name.starts_with("deco") || layer.name == "cheeks";
                        let found =
                            crate::sprite::lookup_exists(art, species.id(), &layer.name, stage);
                        assert!(
                            known || found,
                            "{species:?}/{}: unknown part {}",
                            pose.id(),
                            layer.name
                        );
                    }
                    let s = compose_frame(art, species.id(), frame, None, stage, Extras::default());
                    assert!(
                        s.palette.iter().all(|i| i.light != 0 || i.dark != 0),
                        "{species:?}: a key without a colour"
                    );
                    assert!(
                        s.cells.iter().any(|&c| c != 0),
                        "{species:?}/{}: an empty frame",
                        pose.id()
                    );
                }
            }
        }
    }
}

// ---- the design's reference, frame by frame ---------------------------

#[test]
fn every_frame_matches_the_design_reference() {
    let golden: Value = serde_json::from_str(GOLDEN).unwrap();
    let art = art();
    let mut checked = 0;
    for (key, want) in golden["frames"].as_object().unwrap() {
        let (path, extra) = key
            .split_once('+')
            .map_or((key.as_str(), None), |(p, e)| (p, Some(e)));
        let parts: Vec<&str> = path.split('/').collect();
        let sprite = if parts[0] == "egg" {
            let pose = if parts[1] == "egg" {
                EggPose::Still
            } else {
                EggPose::Ready
            };
            egg(pose, parts[2].parse().unwrap()).unwrap()
        } else {
            let (species, stage, state, i) = (
                parts[0],
                parts[1],
                parts[2],
                parts[3].parse::<usize>().unwrap(),
            );
            let stage = Stage::from_index(stage.parse().unwrap()).unwrap();
            let frame = &art.states(species).unwrap()[state][i];
            let extras = Extras {
                crown: extra == Some("crown"),
                badge: extra == Some("badge"),
                gold: extra == Some("gold"),
            };
            compose_frame(art, species, frame, None, stage, extras)
        };
        let appearance = mode(parts[parts.len() - 1]);
        assert_eq!(digest(&sprite, appearance), want.as_str().unwrap(), "{key}");
        checked += 1;
    }
    assert!(checked > 900, "only {checked} frames checked");
}

#[test]
fn pinned_rolls_traits_mutations_and_frames_match_the_reference() {
    let golden: Value = serde_json::from_str(GOLDEN).unwrap();
    for sample in golden["samples"].as_array().unwrap() {
        let seed = seed_of(sample["seed"].as_str().unwrap());
        let hour = sample["hatch_hour"].as_u64().unwrap() as u8;
        let stage = Stage::from_index(sample["stage"].as_u64().unwrap() as u8).unwrap();
        let g = Genome::roll(&seed, hour);
        let want = &sample["genome"];
        let at = |v: &Value| v.as_u64().unwrap() as usize;
        assert_eq!(
            g.species.id(),
            want["species"],
            "species of {}",
            sample["seed"]
        );
        assert_eq!(usize::from(g.fur), at(&want["palette"]));
        assert_eq!(g.shiny, want["shiny"].as_bool().unwrap());
        assert_eq!(g.pattern as usize, at(&want["pattern"]));
        assert_eq!(g.eyes as usize, at(&want["eyes"]));
        assert_eq!(g.size as usize, at(&want["size"]));
        assert_eq!(g.slot as usize, at(&want["slot"]));

        let (t, history) = evolve(&seed, g, stage);
        let tw = &sample["traits"];
        assert_eq!(usize::from(t.fur), at(&tw["palette"]));
        assert_eq!(t.pattern as usize, at(&tw["pattern"]));
        assert_eq!(t.eyes as usize, at(&tw["eyes"]));
        let grown: Vec<&str> = t.grown.iter().map(|g| g.id()).collect();
        let grown_want: Vec<&str> = tw["grown"]
            .as_array()
            .unwrap()
            .iter()
            .map(|v| v.as_str().unwrap())
            .collect();
        assert_eq!(grown, grown_want);
        let hist: Vec<(u64, &str, String)> = history
            .iter()
            .map(|(k, m)| {
                let (kind, what) = match m {
                    Mutation::Fur(f) => ("palette", art().genome.furs[usize::from(*f)].id.clone()),
                    Mutation::Pattern(p) => (
                        "pattern",
                        ["plain", "spots", "stripes", "patch"][*p as usize].to_owned(),
                    ),
                    Mutation::Grew(g) => ("grown", g.id().to_owned()),
                    Mutation::Eyes(e) => (
                        "eyes",
                        ["round", "lidded", "starry", "button"][*e as usize].to_owned(),
                    ),
                };
                (*k as u64, kind, what)
            })
            .collect();
        let hist_want: Vec<(u64, &str, String)> = sample["history"]
            .as_array()
            .unwrap()
            .iter()
            .map(|h| {
                (
                    h[0].as_u64().unwrap(),
                    h[1].as_str().unwrap(),
                    h[2].as_str().unwrap().to_owned(),
                )
            })
            .collect();
        assert_eq!(hist, hist_want, "history of {}", sample["seed"]);

        let look = Look {
            seed,
            stage,
            hatch_hour: hour,
            flags: 0,
            crowned: false,
        };
        for (key, want) in sample["frames"].as_object().unwrap() {
            let parts: Vec<&str> = key.split('-').collect();
            let pose = Pose::STATES
                .into_iter()
                .find(|p| p.id() == parts[0])
                .unwrap();
            let sprite = look.compose(pose, parts[1].parse().unwrap()).unwrap();
            assert_eq!(
                digest(&sprite, mode(parts[2])),
                want.as_str().unwrap(),
                "{} {key}",
                sample["seed"]
            );
        }
    }
}

// ---- the roll ------------------------------------------------------------

#[test]
fn the_species_follow_their_weights_and_about_one_in_64_is_shiny() {
    let n = 10_000;
    let mut counts: BTreeMap<Species, u32> = BTreeMap::new();
    let mut shiny = 0;
    for i in 0..n {
        let g = Genome::roll(&seed_n(i), 14);
        *counts.entry(g.species).or_default() += 1;
        shiny += u32::from(g.shiny);
        assert!(g.fur <= 9);
    }
    for species in Species::ALL {
        let got = f64::from(counts.get(&species).copied().unwrap_or(0)) / f64::from(n);
        let want = f64::from(species.weight()) / 1000.0;
        assert!(
            (got - want).abs() < 0.015,
            "{species:?}: {got:.3} vs {want:.3}"
        );
    }
    assert_eq!(
        counts.get(&Species::Moth),
        None,
        "the moth only comes at 03:00"
    );
    let expected = f64::from(n) / 64.0;
    assert!(
        (f64::from(shiny) - expected).abs() < 50.0,
        "{shiny} shiny of {n} (~{expected:.0} expected)"
    );
}

#[test]
fn the_same_seed_is_the_same_pet_and_the_seed_alone_decides_it() {
    for i in 0..200 {
        let seed = seed_n(i);
        assert_eq!(Genome::roll(&seed, 14), Genome::roll(&seed, 14));
        assert_eq!(
            Genome::roll(&seed, 9),
            Genome::roll(&seed, 22),
            "only 03:00 changes the roll"
        );
    }
}

// ---- growing up ------------------------------------------------------------

fn finishes(r: &mut PetRecord, device: &str, n: u32) {
    for _ in 0..n {
        r.record_finish(device);
    }
}

#[test]
fn it_grows_after_enough_tasks_and_days_only_while_shown_and_never_back() {
    let t = Thresholds::MEDIUM;
    let t0 = 1_800_000_000;
    let mut r = PetRecord::hatch(seed_n(1), t0, 14);
    assert_eq!(r.stage(), Stage::Hatchling);
    finishes(&mut r, "phone", 9);
    assert_eq!(r.due(t0 + 3 * DAY, &t), None, "9 tasks are not 10");
    r.record_finish("ipad");
    assert_eq!(r.tasks(), 10, "devices add up");
    assert_eq!(r.due(t0 + 3 * DAY - 1, &t), None, "not before three days");
    assert_eq!(
        r.grow(t0 + 3 * DAY, &t, false),
        None,
        "not while it's hidden"
    );
    assert_eq!(r.stage(), Stage::Hatchling);
    assert_eq!(r.grow(t0 + 5 * DAY, &t, true), Some(Stage::Grown));
    assert_eq!(r.stage_at(Stage::Grown), Some(t0 + 5 * DAY));

    let next = r.next_stage(&t).unwrap();
    assert_eq!(
        (next.stage, next.tasks_left, next.not_before),
        (Stage::Seasoned, 90, t0 + 19 * DAY)
    );
    finishes(&mut r, "phone", 90);
    assert_eq!(
        r.grow(t0 + 18 * DAY, &t, true),
        None,
        "14 days after it grew, not after the hatch"
    );
    assert_eq!(r.grow(t0 + 19 * DAY, &t, true), Some(Stage::Seasoned));
    finishes(&mut r, "phone", 500);
    assert_eq!(
        r.grow(t0 + 400 * DAY, &t, true),
        None,
        "seasoned is the last stage"
    );
    assert_eq!(r.next_stage(&t), None);
    assert_eq!(r.stage(), Stage::Seasoned);
}

#[test]
fn the_three_tiers_are_ordered() {
    let (fast, mid, slow) = (Thresholds::FASTER, Thresholds::MEDIUM, Thresholds::SLOWER);
    assert!(fast.grown_tasks < mid.grown_tasks && mid.grown_tasks < slow.grown_tasks);
    assert!(fast.seasoned_tasks < mid.seasoned_tasks && mid.seasoned_tasks < slow.seasoned_tasks);
    assert!(fast.grown_days < mid.grown_days && mid.grown_days < slow.grown_days);
    assert!(fast.seasoned_days < mid.seasoned_days && mid.seasoned_days < slow.seasoned_days);
    assert_eq!(Thresholds::default(), Thresholds::MEDIUM);
}

#[test]
fn mutations_follow_from_the_seed_and_stage_alone() {
    for i in 0..300 {
        let seed = seed_n(i);
        let g = Genome::roll(&seed, 14);
        let (t1, h1) = evolve(&seed, g, Stage::Grown);
        let (t2, h2) = evolve(&seed, g, Stage::Seasoned);
        assert_eq!(
            evolve(&seed, g, Stage::Seasoned),
            (t2.clone(), h2.clone()),
            "deterministic"
        );
        assert!(
            evolve(&seed, g, Stage::Hatchling).1.is_empty(),
            "no mutation before growing"
        );
        assert_eq!(h1.len(), 1);
        assert_eq!(h2.len(), 2);
        assert_eq!(
            h2[0], h1[0],
            "a stage's mutation doesn't depend on the next"
        );
        if g.shiny {
            assert!(t2.shiny && t2.fur == g.fur, "a shiny keeps its colours");
        }
        assert!(t2.grown.len() <= 2 && t1.grown.len() <= 1);
        let heads = t2
            .grown
            .iter()
            .filter(|g| matches!(g, Growth::Sprout | Growth::MossTuft | Growth::Crystal))
            .count();
        assert!(heads <= 1, "one thing on the head");
        for (_, m) in &h2 {
            match m {
                Mutation::Pattern(p) => assert_ne!(*p, Pattern::Plain),
                Mutation::Fur(f) => assert!((1..=9).contains(f)),
                Mutation::Eyes(_) | Mutation::Grew(_) => {}
            }
        }
    }
}

// ---- easter eggs -----------------------------------------------------------

#[test]
fn a_hatch_at_three_brings_the_moth() {
    for i in 0..100 {
        assert_eq!(Genome::roll(&seed_n(i), 3).species, Species::Moth);
    }
    let r = PetRecord::hatch(seed_n(7), 1_800_000_000, 3);
    assert_eq!(r.genome().species, Species::Moth);
    assert!(r.found().contains(&Egg::NightHatch));
    assert!(easter::night_hatch(3) && !easter::night_hatch(2) && !easter::night_hatch(4));
}

#[test]
fn the_first_roam_earns_the_badge_once() {
    let mut r = PetRecord::hatch(seed_n(2), 1_800_000_000, 14);
    assert_eq!(r.record_roam(), Some(Egg::MadeItThrough));
    assert_eq!(r.record_roam(), None);
    assert!(r.found().contains(&Egg::MadeItThrough));
    let look = r.look();
    let with = look.compose(Pose::Idle, 0).unwrap();
    let without = Look { flags: 0, ..look }.compose(Pose::Idle, 0).unwrap();
    assert_ne!(with, without, "the badge shows");
}

#[test]
fn the_thousandth_task_turns_the_outline_gold() {
    let mut r = PetRecord::hatch(seed_n(3), 1_800_000_000, 14);
    let mut found = Vec::new();
    for i in 0..1000u32 {
        found.extend(r.record_finish(if i % 2 == 0 { "phone" } else { "ipad" }));
    }
    assert_eq!(found, vec![Egg::Task1000], "once, at the thousandth");
    assert!(r.found().contains(&Egg::Task1000));
    assert!(easter::gold(1000) && !easter::gold(999));
}

#[test]
fn sudo_wears_a_crown_for_as_long_as_the_name_stands() {
    let mut r = PetRecord::hatch(seed_n(4), 1_800_000_000, 14);
    for name in ["sudo", " SUDO ", "Sudo"] {
        r.rename(name, 1_800_000_100);
        assert!(r.look().crowned, "{name:?}");
    }
    for name in ["sudoer", "su do", "root", ""] {
        r.rename(name, 1_800_000_200);
        assert!(!r.look().crowned, "{name:?}");
    }
}

#[test]
fn seven_taps_inside_two_seconds_start_a_pogo() {
    let mut taps = Taps::default();
    let results: Vec<bool> = (0..7)
        .map(|i| taps.tap(10.0 + f64::from(i) * 0.25))
        .collect();
    assert_eq!(results, [false, false, false, false, false, false, true]);
    assert!(!taps.tap(12.0), "it starts over");
    let mut slow = Taps::default();
    assert!(
        !(0..10).any(|i| slow.tap(f64::from(i) * 0.4)),
        "seven, but not inside two seconds"
    );
    let r = PetRecord::hatch(seed_n(5), 1_800_000_000, 14);
    assert!(r.look().frame_count(Pose::Pogo) > 0);
}

