// ---- the record and sync ---------------------------------------------------

#[test]
fn the_record_round_trips_and_a_newer_one_is_refused() {
    let mut r = PetRecord::hatch(seed_n(8), 1_800_000_000, 9);
    r.rename("Pip", 1_800_000_010);
    r.record_finish("phone");
    let json = r.to_json();
    assert_eq!(PetRecord::from_json(&json), Ok(r.clone()));
    let mut v: Value = serde_json::from_slice(&json).unwrap();
    v["version"] = 2.into();
    assert_eq!(
        PetRecord::from_json(&serde_json::to_vec(&v).unwrap()),
        Err(RecordError::Newer(2))
    );
    assert!(matches!(
        PetRecord::from_json(b"{}"),
        Err(RecordError::Malformed(_))
    ));
    v["version"] = 1.into();
    v["stage"] = 7.into();
    assert!(matches!(
        PetRecord::from_json(&serde_json::to_vec(&v).unwrap()),
        Err(RecordError::Malformed(_))
    ));
}

fn records() -> Vec<PetRecord> {
    let t0 = 1_800_000_000;
    let a = PetRecord::hatch(seed_n(10), t0, 14).with_finishes("phone", 12);
    let mut a2 = a
        .clone()
        .with_finishes("ipad", 5)
        .with_stage(Stage::Grown, t0 + 4 * DAY);
    a2.rename("Pip", t0 + 100);
    let mut a3 = a.clone().with_finishes("phone", 20);
    a3.rename("Bean", t0 + 50);
    a3.record_roam();
    let b = PetRecord::hatch(seed_n(11), t0 - 10, 14).with_finishes("mac", 3);
    let c = PetRecord::hatch(seed_n(12), t0 + 999, 3);
    vec![a, a2, a3, b, c]
}

#[test]
fn merging_is_commutative_associative_and_idempotent() {
    let rs = records();
    for x in &rs {
        assert_eq!(merge(x, x), *x, "idempotent");
        for y in &rs {
            assert_eq!(merge(x, y), merge(y, x), "commutative");
            for z in &rs {
                assert_eq!(
                    merge(&merge(x, y), z),
                    merge(x, &merge(y, z)),
                    "associative"
                );
            }
        }
    }
}

#[test]
fn the_earlier_hatch_wins_and_counts_add_up_without_going_back() {
    let rs = records();
    let (a, a2, a3, b) = (&rs[0], &rs[1], &rs[2], &rs[3]);
    let same = merge(a2, a3);
    assert_eq!(same.seed(), a.seed());
    assert_eq!(same.name(), "Pip", "the last name written");
    assert_eq!(same.stage(), Stage::Grown, "the higher stage");
    assert_eq!(same.tasks(), 25, "phone 20 (the higher count) + ipad 5");
    assert!(same.found().contains(&Egg::MadeItThrough), "flags join");
    let other = merge(&same, b);
    assert_eq!(other.seed(), b.seed(), "the earlier hatch is the pet");
    assert_eq!(other.tasks(), 28, "the person's tasks carry over");
    assert!(merge(&same, a).stage() >= same.stage(), "never back");
}

#[test]
fn reconcile_says_which_side_to_write() {
    let rs = records();
    let none = reconcile(None, None);
    assert_eq!(
        (none.record, none.write_local, none.write_cloud),
        (None, false, false)
    );
    let up = reconcile(Some(&rs[0]), None);
    assert_eq!((up.write_local, up.write_cloud), (false, true));
    let down = reconcile(None, Some(&rs[0]));
    assert_eq!((down.write_local, down.write_cloud), (true, false));
    let both = reconcile(Some(&rs[1]), Some(&rs[2]));
    assert!(both.write_local && both.write_cloud);
    assert_eq!(both.record, Some(merge(&rs[1], &rs[2])));
}

#[test]
fn the_egg_hatches_at_the_first_finish_or_the_third_connection_while_watched() {
    let mut e = EggProgress::default();
    assert!(!e.ready());
    e.connected();
    e.connected();
    assert!(!e.ready());
    e.connected();
    assert!(e.ready());
    let mut f = EggProgress::default();
    f.agent_finished();
    assert!(f.ready());
    assert!(may_hatch(&f, true, true, true));
    assert!(!may_hatch(&f, false, true, true), "only on Home");
    assert!(
        !may_hatch(&f, true, false, true),
        "only with the companion shown"
    );
    assert!(
        !may_hatch(&f, true, true, false),
        "only once iCloud has settled"
    );
    for pose in [EggPose::Still, EggPose::Ready] {
        assert!(egg(pose, 0).is_some());
    }
}

#[test]
fn three_taps_wobble_crack_and_hatch_the_egg_and_a_relaunch_starts_over() {
    let mut e = EggProgress::default();
    assert_eq!(e.tap(), 1, "a wobble");
    assert!(!e.cracked() && !e.hatchable());
    assert_eq!(e.tap(), 2);
    assert!(e.cracked() && !e.hatchable(), "cracked, not yet hatched");
    assert!(!may_hatch(&e, true, true, true));
    assert_eq!(e.tap(), 3);
    assert!(
        e.hatchable() && !e.ready(),
        "hatched by hand, not by itself"
    );
    assert!(may_hatch(&e, true, true, true));
    assert!(
        !may_hatch(&e, true, true, false),
        "not before iCloud settles: then, once it has"
    );
    assert_eq!(e.tap(), 3, "it stops counting");
    // The taps are kept in memory only.
    let kept: EggProgress = serde_json::from_str(&serde_json::to_string(&e).unwrap()).unwrap();
    assert_eq!(kept.taps, 0);
    // Ready by itself, it's cracked and hatches with no tap, as before.
    let mut f = EggProgress::default();
    f.agent_finished();
    assert!(f.cracked() && f.hatchable() && f.taps == 0);
}

// ---- drawing and the Live Activity ----------------------------------------

#[test]
fn every_pose_of_every_pet_encodes_small_and_decodes_exactly() {
    let mut biggest = 0;
    for i in 0..40 {
        for stage in Stage::ALL {
            for hour in [14, 3] {
                let look = Look {
                    seed: seed_n(i),
                    stage,
                    hatch_hour: hour,
                    flags: 3,
                    crowned: i % 5 == 0,
                };
                for pose in Pose::STATES.into_iter().chain([Pose::Hatch, Pose::Pogo]) {
                    for f in 0..look.frame_count(pose) {
                        let s = look.compose(pose, f).unwrap();
                        assert_eq!(s.side, 24);
                        let e = s.encode();
                        biggest = biggest.max(e.len());
                        assert_eq!(Sprite::decode(&e), Ok(s), "{pose:?} {f}");
                    }
                    assert!(look.compose(pose, look.frame_count(pose)).is_none());
                    assert_eq!(look.durations(pose).len(), look.frame_count(pose));
                }
            }
        }
    }
    assert!(biggest <= 520, "a pose encodes to {biggest} bytes");
}

#[test]
fn a_broken_string_is_not_a_sprite() {
    for bad in [
        "",
        "px1:",
        "px2:AAAA",
        "px1:!!!!",
        "px1:AQIB",
        "px1:AxgB",
        "px1:ARgAAA==",
    ] {
        assert!(Sprite::decode(bad).is_err(), "{bad:?}");
    }
    let s = Sprite {
        side: 2,
        cells: vec![0, 1, 1, 0],
        palette: vec![crate::sprite::Ink {
            light: 0x123456,
            dark: 0xABCDEF,
        }],
    };
    let e = s.encode();
    assert_eq!(Sprite::decode(&e), Ok(s.clone()));
    assert_eq!(s.color(1, 0, Appearance::Dark), Some(0xABCDEF));
    assert_eq!(s.color(0, 0, Appearance::Light), None);
    assert_eq!(s.color(5, 5, Appearance::Light), None);
}

#[test]
fn the_live_activitys_format_is_pinned() {
    // Tests/MoshpitTests/Island/PixelSpriteTests.swift decodes this string.
    let s = Sprite {
        side: 2,
        cells: vec![0, 1, 1, 0],
        palette: vec![crate::sprite::Ink {
            light: 0x123456,
            dark: 0xABCDEF,
        }],
    };
    assert_eq!(s.encode(), "px1:AQIBARI0VqvN7wAJAA==");
}

#[test]
fn traits_change_the_picture() {
    let seed = seed_n(20);
    let base = Look {
        seed,
        stage: Stage::Grown,
        hatch_hour: 14,
        flags: 0,
        crowned: false,
    };
    let idle = base.compose(Pose::Idle, 0).unwrap();
    let hatchling = Look {
        stage: Stage::Hatchling,
        ..base
    }
    .compose(Pose::Idle, 0)
    .unwrap();
    let crowned = Look {
        crowned: true,
        ..base
    }
    .compose(Pose::Idle, 0)
    .unwrap();
    assert_ne!(idle, hatchling);
    assert_ne!(idle, crowned);
    let g = Genome {
        species: Species::Tun,
        fur: 0,
        shiny: false,
        pattern: Pattern::Plain,
        eyes: Eyes::Round,
        size: Size::Standard,
        slot: Slot::Head,
    };
    assert_eq!(evolve(&seed, g, Stage::Hatchling).0.grown, vec![]);
}
